class Solution {
    public int largestAltitude(int[] gain){
        int altitude=0,highest=0;
        for(int change:gain){
            altitude+=change;
            highest=Math.max(highest,altitude);
        }
        return highest;
    }
}

code.kotlin:
class Solution {
    fun largestAltitude(gain:IntArray):Int{
        var altitude=0;
        var highest=0;
        for(change in gain){
            altitude+=change;
            highest=maxOf(highest,altitude)
        };
        return highest
    }
}

code.cpp:
class Solution {
    public: int largestAltitude(vector<int>& gain){
        int altitude=0,highest=0;
        for(int change:gain){
            altitude+=change;
            highest=max(highest,altitude);
        }
        return highest;
    }
};
